//! Theme — iced `Theme` with a sola-flavored extended palette.
//!
//! The kit hands every iced widget a `Theme::custom_with_fn`-built theme
//! whose `Extended` palette is generated by [`build_theme`]'s binding
//! closure instead of iced's default `Extended::generate`. That
//! generator is the kit's **binding layer** — it decides which of the
//! 10 hex atoms in [`hex`]
//! lands in each of iced's slots (`background.weaker`, `primary.strong`,
//! …). Component style fns then read from `theme.extended_palette()`
//! exactly like iced's own `button::primary` does. No global state, no
//! side struct.
//!
//! The legacy CEF kit ran the same atoms→bindings→component mapping in
//! CSS; here it's typed Rust against iced's existing palette vocabulary.
//! See `docs/vault/sola-kit.md` for the migration story.
//!
//! ## Mapping rationale
//!
//! Iced's `Background` has 8 tiers (weakest…base…strongest). We have
//! 4 background atoms (BG, BG_RAISED, BG_HOVER, BORDER). The mapping
//! biases toward exposing each atom on the slot iced apps reach for
//! first:
//!
//! | iced slot                | sola atom    | typical use                |
//! | ------------------------ | ------------ | -------------------------- |
//! | `background.base`        | `BG`         | window canvas              |
//! | `background.weakest`     | `BG`         | scrollable backgrounds     |
//! | `background.weaker`      | `BG_RAISED`  | sidebars, cards            |
//! | `background.weak`        | `BG_RAISED`  | (alias of weaker)          |
//! | `background.neutral`     | `BG_HOVER`   | between elevations         |
//! | `background.strong`      | `BG_HOVER`   | hover / selected rows      |
//! | `background.stronger`    | `BORDER`     | hairlines                  |
//! | `background.strongest`   | `BORDER`     | (alias of stronger)        |
//!
//! `primary.base` = `ACCENT`. `secondary.base` = `BORDER` with
//! `FG_MUTED` as the `text` pair, giving us muted-text-on-border for
//! deemphasized chrome. `success`/`warning`/`danger` map straight to
//! their atoms; iced auto-derives weak/strong tiers we don't need to
//! pin.

use iced::{Color, Theme};
use iced::theme::palette::{
    Background, Danger, Extended, Pair, Palette, Primary, Secondary, Success, Warning,
};

use sola_core::theme::Theme as BusTheme;

/// Theme name reported by `Theme::name()` — appears in `pick_list`
/// theme switchers and in the iced debug overlay.
pub const THEME_NAME: &str = "sola";

pub mod hex {
    // Graphite dark palette — sola-kit-ds / sola-agent-ds pass.
    // Cool blue-greys with cyan accent; denser contrast than mac greys.
    /// Window / canvas base.
    pub const BG: &str = "#0c0e12";
    /// Primary label.
    pub const FG: &str = "#e9ecf2";
    /// Sparse accent (selection chrome, focus, key status).
    pub const ACCENT: &str = "#3dd6f5";
    pub const SUCCESS: &str = "#3ecf8e";
    pub const WARNING: &str = "#e8b84a";
    pub const DANGER: &str = "#f07178";
    /// Muted / secondary label.
    pub const FG_MUTED: &str = "#8b94a8";
    /// Raised panel / sidebar / card.
    pub const BG_RAISED: &str = "#151922";
    /// Hover lift.
    pub const BG_HOVER: &str = "#1e2533";
    /// Hairline separators.
    pub const BORDER: &str = "#2a3344";
    /// Selected-row fill — quiet accent-tinted.
    /// iced has no selection slot — see
    /// [`super::install_selection`] / [`super::selection`].
    pub const SELECTION: &str = "#163842";
}

/// Build the kit's iced theme from its compile-time default atoms.
/// Apps call this from their `theme(&self)` callback; the returned
/// `Theme::Custom` is cheap to clone (it wraps an `Arc<Custom>`).
pub fn default_theme() -> Theme {
    build_theme(&Atoms::default())
}

/// Theme for an OS-transparent overlay window (menu / launcher / switcher).
///
/// The window fill is painted from `extended_palette().background.base.color`
/// (iced 0.14). We start from the base theme's **sola** `Extended` binding
/// (raised / hover / border ladder intact) and force only
/// `background.base.color` transparent so the area around kit chrome stays
/// see-through. Do **not** route through iced's `Extended::generate` — that
/// drops the atom→slot map and washes shell chrome with mid-greys.
pub fn overlay(base: &Theme) -> Theme {
    let palette = base.palette();
    let mut ext = *base.extended_palette();
    // Keep base.text and every other tier; only the window fill goes clear.
    ext.background.base.color = Color::TRANSPARENT;
    Theme::custom_with_fn("sola-overlay".to_string(), palette, move |_| ext)
}

/// Theme for the menubar. `bg` is the menubar background
/// (`shell-menubar-bg` — black by default).
///
/// Starts from the base theme's sola `Extended` so primary / secondary /
/// raised / hover / border mappings stay correct for kit buttons. Only
/// `background.base` and `background.weakest` rebind to the menubar fill;
/// mid-tiers keep the sola ladder (row hovers use `button::menubar` alpha,
/// not `background.strong`).
pub fn menubar(base: &Theme, bg: Color) -> Theme {
    let mut palette = base.palette();
    palette.background = bg;
    let mut ext = *base.extended_palette();
    let fg = ext.background.base.text;
    ext.background.base = Pair::new(bg, fg);
    // weakest aliases base for scrollables — keep menubar strip consistent.
    ext.background.weakest = Pair::new(bg, fg);
    Theme::custom_with_fn("sola-menubar".to_string(), palette, move |_| ext)
}

/// The binding layer — maps the kit's 10 colour atoms into iced's
/// `Extended` palette slots. This is the **single** place the
/// atom→slot layout lives; every theme the kit builds
/// ([`build_theme`], hence [`default_theme`] and [`theme_from_bus`])
/// routes through here. Component style fns read the resulting slots
/// via `theme.extended_palette()`; no component references `hex::*`
/// directly unless escape-hatching.
fn extended_from_atoms(a: &Atoms) -> Extended {
    // `selection` is intentionally not bound — it has no iced palette
    // slot and is delivered via the process-wide cell, not this binding.
    let Atoms {
        bg, bg_raised, bg_hover, border, fg, fg_muted, accent, success, warning, danger,
        selection: _,
    } = *a;
    Extended {
        background: Background {
            base: Pair::new(bg, fg),
            weakest: Pair::new(bg, fg),
            weaker: Pair::new(bg_raised, fg),
            weak: Pair::new(bg_raised, fg),
            neutral: Pair::new(bg_hover, fg),
            strong: Pair::new(bg_hover, fg),
            stronger: Pair::new(border, fg),
            strongest: Pair::new(border, fg),
        },
        // ACCENT — let iced derive weak/strong shades, no need to
        // hand-pin every tier when our palette is a single atom.
        primary: Primary::generate(accent, bg, fg),
        // Carries our muted-chrome story: secondary.base.color = BORDER,
        // .text = FG_MUTED. Style fns that want "deemphasized text on
        // a hairline-coloured surface" read from here.
        secondary: Secondary {
            base: Pair::new(border, fg_muted),
            weak: Pair::new(bg_hover, fg_muted),
            strong: Pair::new(border, fg),
        },
        success: Success::generate(success, bg, fg),
        warning: Warning::generate(warning, bg, fg),
        danger: Danger::generate(danger, bg, fg),
        is_dark: true,
    }
}

/// Build an iced `Theme` from an editable atom set — the one primitive
/// every other theme constructor composes. The base `Palette` carries
/// the headline atoms (so `theme.palette()` is sensible) while the
/// generator closure installs the full sola binding via
/// [`extended_from_atoms`].
pub fn build_theme(atoms: &Atoms) -> Theme {
    let a = *atoms;
    Theme::custom_with_fn(
        THEME_NAME.to_string(),
        Palette {
            background: a.bg,
            text: a.fg,
            primary: a.accent,
            success: a.success,
            warning: a.warning,
            danger: a.danger,
        },
        move |_| extended_from_atoms(&a),
    )
}

/// Process-wide selected-row highlight colour. iced's `Extended`
/// palette has no selection slot, so — exactly like the font role table
/// (`crate::fonts`) — this rides a process-wide cell reinstalled on
/// every live theme build and every bus `Topic::Theme` delivery.
/// Component style fns read it via [`selection`]; the storybook and the
/// bus consumer path both refresh it via [`install_selection`].
static SELECTION: std::sync::LazyLock<std::sync::RwLock<Color>> =
    std::sync::LazyLock::new(|| std::sync::RwLock::new(parse(hex::SELECTION)));

/// Swap the process-wide selection colour. Re-callable — the storybook
/// calls it as the user edits the `selection` atom, and the bus theme
/// consumer path calls it on every `Topic::Theme` so a selection edit
/// propagates everywhere on the next render.
pub fn install_selection(color: Color) {
    if let Ok(mut guard) = SELECTION.write() {
        *guard = color;
    }
}

/// The current selected-row highlight colour. Falls back to the
/// compile-time default ([`hex::SELECTION`]) if the lock is poisoned.
pub fn selection() -> Color {
    SELECTION
        .read()
        .map(|c| *c)
        .unwrap_or_else(|_| parse(hex::SELECTION))
}

/// Parse `#rrggbb` / `#rrggbbaa` into an iced `Color`. Panics on
/// malformed input — the inputs are compile-time constants in this
/// crate, so the panic is a self-check rather than a runtime concern.
pub fn parse(s: &str) -> Color {
    try_parse(s).unwrap_or_else(|| panic!("expected #rrggbb or #rrggbbaa, got {s:?}"))
}

/// Try to parse `#rrggbb` or `#rrggbbaa`, returning `None` on malformed
/// input. Used when ingesting bus theme atoms whose values arrive as
/// untrusted strings — a malformed swatch becomes a fallback rather than
/// a panic — and by the color picker's free-text hex field.
pub fn try_parse(s: &str) -> Option<Color> {
    let s = s.trim_start_matches('#');
    if s.len() != 6 && s.len() != 8 {
        return None;
    }
    let r = u8::from_str_radix(&s[0..2], 16).ok()? as f32 / 255.0;
    let g = u8::from_str_radix(&s[2..4], 16).ok()? as f32 / 255.0;
    let b = u8::from_str_radix(&s[4..6], 16).ok()? as f32 / 255.0;
    let a = if s.len() == 8 {
        u8::from_str_radix(&s[6..8], 16).ok()? as f32 / 255.0
    } else {
        1.0
    };
    Some(Color { r, g, b, a })
}

/// Translate a bus theme (`sola_core::theme::Theme`) into the kit's
/// iced `Theme`. **Pure**: reads the colour atoms via
/// [`atoms_from_bus_theme`] and builds via [`build_theme`]; it does
/// *not* mutate the process font table. Pair it with an explicit
/// `fonts::install(fonts_from_bus_theme(bus))` (or use the
/// `sola_kit::apply_theme_update` helper, which does both):
///
/// ```ignore
/// Msg::Bus(msg) => {
///     if let Topic::Theme(bus) = &msg.topic {
///         self.theme = sola_kit::theme::theme_from_bus(bus);
///         sola_kit::fonts::install(sola_kit::theme::fonts_from_bus_theme(bus));
///     }
/// }
/// ```
///
/// Then return `self.theme.clone()` from `App::theme(&self)`.
pub fn theme_from_bus(bus: &BusTheme) -> Theme {
    build_theme(&atoms_from_bus_theme(bus))
}

/// Produce a bus theme (`sola_core::theme::Theme`) representing the
/// kit's compile-time default palette. Defined as the canonical
/// round-trip of the default atoms, so what the shell broadcasts at
/// boot reads back as exactly [`Atoms::default`] / [`default_theme`] —
/// no drift between the pre-replay frame and the seeded steady state.
pub fn to_bus_theme() -> BusTheme {
    bus_theme_from_atoms(&Atoms::default())
}


/// Editable atom set — every colour the iced kit's theme depends on,
/// held as `iced::Color` so the storybook can mutate one and rebuild.
///
/// This is the bridge between the kit's compile-time palette (the
/// `hex::*` constants) and the bus-side `BusTheme` schema. Both
/// directions go through here:
///
///   default constants → `Atoms::default`
///   `Atoms` → `iced::Theme` via [`build_theme`]
///   `Atoms` → `BusTheme`   via [`bus_theme_from_atoms`]
///
/// The storybook's editor mutates an `Atoms` value, then rebuilds and
/// re-emits both forms; other kit apps consume the bus form via
/// [`theme_from_bus`] and pick up the change on their next render.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Atoms {
    pub bg: Color,
    pub bg_raised: Color,
    pub bg_hover: Color,
    pub border: Color,
    pub fg: Color,
    pub fg_muted: Color,
    pub accent: Color,
    pub success: Color,
    pub warning: Color,
    pub danger: Color,
    /// Selected-row highlight. Unlike the others this has no iced palette
    /// slot — it's delivered process-wide via [`install_selection`] and
    /// read by component style fns through [`selection`]. Still part of
    /// `Atoms` so it edits, defaults, and round-trips on the bus like any
    /// other atom.
    pub selection: Color,
}

impl Default for Atoms {
    fn default() -> Self {
        Self {
            bg: parse(hex::BG),
            bg_raised: parse(hex::BG_RAISED),
            bg_hover: parse(hex::BG_HOVER),
            border: parse(hex::BORDER),
            fg: parse(hex::FG),
            fg_muted: parse(hex::FG_MUTED),
            accent: parse(hex::ACCENT),
            success: parse(hex::SUCCESS),
            warning: parse(hex::WARNING),
            danger: parse(hex::DANGER),
            selection: parse(hex::SELECTION),
        }
    }
}

/// One row of the atom ⇄ bus-token mapping: which `Atoms` field a given
/// palette token drives, and the compile-time fallback used when the
/// token is missing or malformed.
///
/// **This is the single source of truth** consulted by both
/// [`atoms_from_bus_theme`] (read) and [`bus_theme_from_atoms`]
/// (write), so the read- and write-lists can never drift apart — the
/// drift that used to make `warning` silently fail to persist. To make
/// a new atom editable, add one row here.
struct AtomBinding {
    /// Bus palette token name.
    token: &'static str,
    /// Compile-time `hex::*` fallback when the token is absent/malformed.
    fallback: &'static str,
    /// Read the atom's value out of an `Atoms`.
    get: fn(&Atoms) -> Color,
    /// Write a value into the matching `Atoms` field.
    set: fn(&mut Atoms, Color),
}

const ATOM_BINDINGS: &[AtomBinding] = &[
    AtomBinding { token: "bg-primary",    fallback: hex::BG,        get: |a| a.bg,        set: |a, c| a.bg = c },
    AtomBinding { token: "bg-secondary",  fallback: hex::BG_RAISED, get: |a| a.bg_raised, set: |a, c| a.bg_raised = c },
    // Hover elevation reads the seed's real `bg-hover`, not `bg-tertiary`.
    AtomBinding { token: "bg-hover",      fallback: hex::BG_HOVER,  get: |a| a.bg_hover,  set: |a, c| a.bg_hover = c },
    AtomBinding { token: "border",        fallback: hex::BORDER,    get: |a| a.border,    set: |a, c| a.border = c },
    AtomBinding { token: "text-primary",  fallback: hex::FG,        get: |a| a.fg,        set: |a, c| a.fg = c },
    AtomBinding { token: "text-tertiary", fallback: hex::FG_MUTED,  get: |a| a.fg_muted,  set: |a, c| a.fg_muted = c },
    AtomBinding { token: "accent",        fallback: hex::ACCENT,    get: |a| a.accent,    set: |a, c| a.accent = c },
    AtomBinding { token: "success",       fallback: hex::SUCCESS,   get: |a| a.success,   set: |a, c| a.success = c },
    AtomBinding { token: "warning",       fallback: hex::WARNING,   get: |a| a.warning,   set: |a, c| a.warning = c },
    AtomBinding { token: "danger",        fallback: hex::DANGER,    get: |a| a.danger,    set: |a, c| a.danger = c },
    // No iced palette slot; round-trips on the bus, delivered process-wide.
    AtomBinding { token: "selection",     fallback: hex::SELECTION, get: |a| a.selection, set: |a, c| a.selection = c },
];

/// Build a `BusTheme` from an editable atom set, writing every token in
/// [`ATOM_BINDINGS`]. Starts from the seed, so atoms the kit doesn't
/// model (`accent-dim`, `text-secondary`, sizes, radii, …) keep their
/// seed values; the kit's own tokens are overwritten — and inserted if
/// the seed somehow lacks them, preserving the write-list ⊇ read-list
/// invariant.
pub fn bus_theme_from_atoms(atoms: &Atoms) -> BusTheme {
    use sola_core::theme::{Token, TokenKind};
    let mut t = BusTheme::default();
    for binding in ATOM_BINDINGS {
        let value = color_to_hex((binding.get)(atoms));
        match t.palette.tokens.get_mut(binding.token) {
            Some(tok) => tok.value = value,
            None => {
                t.palette.tokens.insert(
                    binding.token.to_string(),
                    Token::new(TokenKind::Color, &value, &[]),
                );
            }
        }
    }
    t
}


/// Per-role family selection — what `Topic::Theme` carries on the wire
/// for the kit's font roles. Defaults match seed strings (SF Pro Text +
/// Iosevka Term Slab); [`crate::fonts::fonts_from_families`] falls back
/// when a face is not installed.
#[derive(Debug, Clone)]
pub struct FontSelection {
    pub ui: String,
    pub ui_medium: String,
    pub display: String,
    pub chrome: String,
    pub mono: String,
}

impl Default for FontSelection {
    fn default() -> Self {
        Self {
            ui: crate::fonts::DEFAULT_UI_FAMILY.to_string(),
            ui_medium: crate::fonts::DEFAULT_UI_FAMILY.to_string(),
            display: crate::fonts::DEFAULT_UI_FAMILY.to_string(),
            chrome: crate::fonts::DEFAULT_UI_FAMILY.to_string(),
            mono: crate::fonts::DEFAULT_MONO_FAMILY.to_string(),
        }
    }
}

/// Merge font role selections into a `BusTheme`. Adds five
/// `FontFamily`-kind tokens — `font-ui`, `font-ui-medium`, `font-display`,
/// `font-chrome`, `font-mono` — so consumers can read them out via
/// [`fonts_from_bus_theme`] and reinstall the role table.
pub fn bus_theme_with_fonts(mut t: BusTheme, fonts: &FontSelection) -> BusTheme {
    use sola_core::theme::{Token, TokenKind};
    let writes = [
        ("font-ui",        fonts.ui.clone()),
        ("font-ui-medium", fonts.ui_medium.clone()),
        ("font-display",   fonts.display.clone()),
        ("font-chrome",    fonts.chrome.clone()),
        ("font-mono",      fonts.mono.clone()),
    ];
    for (name, value) in writes {
        t.palette.tokens.insert(
            name.to_string(),
            Token::new(TokenKind::FontFamily, &value, &["font-family"]),
        );
    }
    t
}

/// Build a complete `BusTheme` from an atoms + fonts pair. Convenience
/// over chaining [`bus_theme_from_atoms`] and [`bus_theme_with_fonts`].
pub fn bus_theme_from(atoms: &Atoms, fonts: &FontSelection) -> BusTheme {
    bus_theme_with_fonts(bus_theme_from_atoms(atoms), fonts)
}

/// Read the kit's font role tokens out of a `BusTheme` and build a
/// `crate::fonts::Fonts` table. Missing tokens fall back to the
/// process-wide default font selection.
pub fn fonts_from_bus_theme(bus: &BusTheme) -> crate::fonts::Fonts {
    let default = FontSelection::default();
    let read = |name: &str, fallback: &str| {
        bus.palette
            .tokens
            .get(name)
            .map(|t| t.value.clone())
            .unwrap_or_else(|| fallback.to_string())
    };
    let ui = read("font-ui", &default.ui);
    let ui_medium = read("font-ui-medium", &default.ui_medium);
    let display = read("font-display", &default.display);
    let chrome = read("font-chrome", &default.chrome);
    let mono = read("font-mono", &default.mono);
    crate::fonts::fonts_from_families(&ui, &ui_medium, &display, &chrome, &mono)
}


/// Read the colour atoms out of a `BusTheme` (the inverse of
/// [`bus_theme_from_atoms`]). Missing or malformed tokens fall back to
/// the kit's compile-time defaults, so a partial bus theme still
/// produces a usable `Atoms`. Table-driven via [`ATOM_BINDINGS`].
pub fn atoms_from_bus_theme(bus: &BusTheme) -> Atoms {
    let mut atoms = Atoms::default();
    for binding in ATOM_BINDINGS {
        let color = bus
            .palette
            .tokens
            .get(binding.token)
            .and_then(|t| try_parse(&t.value))
            .unwrap_or_else(|| parse(binding.fallback));
        (binding.set)(&mut atoms, color);
    }
    atoms
}

/// Read the font roles out of a `BusTheme` as a `FontSelection`
/// (string family names). Sibling to [`fonts_from_bus_theme`], which
/// returns the resolved `crate::fonts::Fonts` table.
pub fn font_selection_from_bus_theme(bus: &BusTheme) -> FontSelection {
    let default = FontSelection::default();
    let read = |name: &str, fallback: &str| {
        bus.palette
            .tokens
            .get(name)
            .map(|t| t.value.clone())
            .unwrap_or_else(|| fallback.to_string())
    };
    FontSelection {
        ui: read("font-ui", &default.ui),
        ui_medium: read("font-ui-medium", &default.ui_medium),
        display: read("font-display", &default.display),
        chrome: read("font-chrome", &default.chrome),
        mono: read("font-mono", &default.mono),
    }
}

/// Format an iced `Color` as `#rrggbb`, or `#rrggbbaa` when alpha < 1 —
/// so existing opaque values don't churn on round-trip. The inverse of
/// [`parse`]; shared with the storybook's atom grid so it doesn't
/// reimplement the conversion.
pub fn color_to_hex(c: Color) -> String {
    let r = (c.r * 255.0).round().clamp(0.0, 255.0) as u8;
    let g = (c.g * 255.0).round().clamp(0.0, 255.0) as u8;
    let b = (c.b * 255.0).round().clamp(0.0, 255.0) as u8;
    if c.a < 1.0 {
        let a = (c.a * 255.0).round().clamp(0.0, 255.0) as u8;
        format!("#{r:02x}{g:02x}{b:02x}{a:02x}")
    } else {
        format!("#{r:02x}{g:02x}{b:02x}")
    }
}

// ── Shell customization (shell-* tokens) ────────────────────────────

/// Seed string values for the `shell-*` tokens. Must match
/// `Palette::seed` in sola-core byte-for-byte — `resync_active_theme`
/// matches presets to live themes by value equality, so a drift here
/// would unmatch every untouched preset.
///
/// Menubar stays near-black (opaque greys first; blur deferred). Switcher
/// is a Cmd+Tab-style HUD: neutral frosted pill, soft light plate under
/// the selected icon (not an accent pill).
const SHELL_MENUBAR_BG: &str = "#000000";
const SHELL_BACKDROP_DIM: &str = "#00000099";
const SHELL_SWITCHER_BG: &str = "#1c1c1ee6"; // more opaque HUD glass
const SHELL_SWITCHER_BORDER: &str = "#ffffff1a";
const SHELL_SWITCHER_ICON_BG: &str = "#ffffff2e"; // soft raised plate under icon
const SHELL_SWITCHER_ICON_FG: &str = "#f5f5f7";
const SHELL_SWITCHER_ICON_FG_SEL: &str = "#f5f5f7";
// Compact frame around a large-icon strip.
const SHELL_SWITCHER_PAD: f32 = 14.0;
const SHELL_SWITCHER_TILE_PAD: f32 = 8.0;
// Spotlight-ish defaults: slightly narrower than a settings form; compact rows.
const SHELL_LAUNCHER_WIDTH: f32 = 560.0;
const SHELL_LAUNCHER_PAD: f32 = 8.0;

/// sola-shell's customizable chrome, extracted from the bus theme's
/// `shell-*` tokens. Colors carry alpha (the switcher backplate fill is
/// translucent by design); spacing values are plain pixels.
///
/// Switcher HUD: frame pad is vertical; horizontal = pad + 8 on the
/// pill. Tile pad is icon-cell inset. Launcher rows: vertical =
/// launcher_pad, horizontal = pad + 4.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ShellStyle {
    pub menubar_bg: Color,
    pub backdrop_dim: Color,
    pub switcher_bg: Color,
    pub switcher_border: Color,
    pub switcher_icon_bg: Color,
    pub switcher_icon_fg: Color,
    pub switcher_icon_fg_sel: Color,
    pub switcher_pad: f32,
    pub switcher_tile_pad: f32,
    pub launcher_width: f32,
    pub launcher_pad: f32,
}

impl Default for ShellStyle {
    fn default() -> Self {
        Self {
            menubar_bg: parse(SHELL_MENUBAR_BG),
            backdrop_dim: parse(SHELL_BACKDROP_DIM),
            switcher_bg: parse(SHELL_SWITCHER_BG),
            switcher_border: parse(SHELL_SWITCHER_BORDER),
            switcher_icon_bg: parse(SHELL_SWITCHER_ICON_BG),
            switcher_icon_fg: parse(SHELL_SWITCHER_ICON_FG),
            switcher_icon_fg_sel: parse(SHELL_SWITCHER_ICON_FG_SEL),
            switcher_pad: SHELL_SWITCHER_PAD,
            switcher_tile_pad: SHELL_SWITCHER_TILE_PAD,
            launcher_width: SHELL_LAUNCHER_WIDTH,
            launcher_pad: SHELL_LAUNCHER_PAD,
        }
    }
}

/// One color token, falling back on missing/malformed.
fn shell_color(bus: &BusTheme, token: &str, fallback: Color) -> Color {
    bus.palette
        .tokens
        .get(token)
        .and_then(|t| try_parse(&t.value))
        .unwrap_or(fallback)
}

/// One `"<n>px"` space token, falling back on missing/malformed.
fn shell_space(bus: &BusTheme, token: &str, fallback: f32) -> f32 {
    bus.palette
        .tokens
        .get(token)
        .and_then(|t| t.value.trim().strip_suffix("px")?.trim().parse::<f32>().ok())
        .unwrap_or(fallback)
}

/// Read the shell style out of a `BusTheme` (the inverse of
/// [`bus_theme_with_shell`]). Missing or malformed tokens fall back
/// per-field to the compile-time defaults, so a stale preset (saved
/// before the shell tokens existed) renders exactly as before.
pub fn shell_style_from_bus_theme(bus: &BusTheme) -> ShellStyle {
    let d = ShellStyle::default();
    ShellStyle {
        menubar_bg: shell_color(bus, "shell-menubar-bg", d.menubar_bg),
        backdrop_dim: shell_color(bus, "shell-backdrop-dim", d.backdrop_dim),
        switcher_bg: shell_color(bus, "shell-switcher-bg", d.switcher_bg),
        switcher_border: shell_color(bus, "shell-switcher-border", d.switcher_border),
        switcher_icon_bg: shell_color(bus, "shell-switcher-icon-bg", d.switcher_icon_bg),
        switcher_icon_fg: shell_color(bus, "shell-switcher-icon-fg", d.switcher_icon_fg),
        switcher_icon_fg_sel: shell_color(bus, "shell-switcher-icon-fg-sel", d.switcher_icon_fg_sel),
        switcher_pad: shell_space(bus, "shell-switcher-pad", d.switcher_pad),
        switcher_tile_pad: shell_space(bus, "shell-switcher-tile-pad", d.switcher_tile_pad),
        launcher_width: shell_space(bus, "shell-launcher-width", d.launcher_width),
        launcher_pad: shell_space(bus, "shell-launcher-pad", d.launcher_pad),
    }
}

/// Write `shell`'s values into `t`'s palette as `shell-*` tokens
/// (the inverse of [`shell_style_from_bus_theme`]). Mirrors
/// `bus_theme_from_atoms`'s upsert behavior — overwrite when present,
/// insert when the seed somehow lacks the token — preserving the
/// write-list ⊇ read-list invariant.
pub fn bus_theme_with_shell(mut t: BusTheme, shell: &ShellStyle) -> BusTheme {
    use sola_core::theme::{Token, TokenKind};
    let entries: [(&str, TokenKind, String); 11] = [
        ("shell-menubar-bg", TokenKind::Color, color_to_hex(shell.menubar_bg)),
        ("shell-backdrop-dim", TokenKind::Color, color_to_hex(shell.backdrop_dim)),
        ("shell-switcher-bg", TokenKind::Color, color_to_hex(shell.switcher_bg)),
        ("shell-switcher-border", TokenKind::Color, color_to_hex(shell.switcher_border)),
        ("shell-switcher-icon-bg", TokenKind::Color, color_to_hex(shell.switcher_icon_bg)),
        ("shell-switcher-icon-fg", TokenKind::Color, color_to_hex(shell.switcher_icon_fg)),
        ("shell-switcher-icon-fg-sel", TokenKind::Color, color_to_hex(shell.switcher_icon_fg_sel)),
        ("shell-switcher-pad", TokenKind::Space, format!("{}px", shell.switcher_pad)),
        ("shell-switcher-tile-pad", TokenKind::Space, format!("{}px", shell.switcher_tile_pad)),
        ("shell-launcher-width", TokenKind::Space, format!("{}px", shell.launcher_width)),
        ("shell-launcher-pad", TokenKind::Space, format!("{}px", shell.launcher_pad)),
    ];
    for (name, kind, value) in entries {
        match t.palette.tokens.get_mut(name) {
            Some(tok) => tok.value = value,
            None => {
                t.palette
                    .tokens
                    .insert(name.to_string(), Token::new(kind, &value, &["shell"]));
            }
        }
    }
    t
}

#[cfg(test)]
mod tests {
    use super::*;

    // A2: every editable atom — including `warning` — must survive a
    // round-trip through the bus theme. Regression guard for the
    // writelist that used to omit `warning`.
    #[test]
    fn all_atoms_round_trip_through_bus() {
        let atoms = Atoms {
            bg: parse("#010203"),
            bg_raised: parse("#040506"),
            bg_hover: parse("#070809"),
            border: parse("#0a0b0c"),
            fg: parse("#0d0e0f"),
            fg_muted: parse("#101112"),
            accent: parse("#131415"),
            success: parse("#161718"),
            warning: parse("#191a1b"),
            danger: parse("#1c1d1e"),
            selection: parse("#1f2021"),
        };
        assert_eq!(atoms_from_bus_theme(&bus_theme_from_atoms(&atoms)), atoms);
    }

    #[test]
    fn default_selection_matches_constant() {
        assert_eq!(Atoms::default().selection, parse(hex::SELECTION));
    }

    #[test]
    fn missing_selection_token_falls_back_to_default() {
        // A bus theme lacking the `selection` token must still resolve to
        // the compile-time default, not transparent/black.
        let mut bus = bus_theme_from_atoms(&Atoms::default());
        bus.palette.tokens.remove("selection");
        assert_eq!(
            atoms_from_bus_theme(&bus).selection,
            parse(hex::SELECTION),
            "absent selection token should fall back to hex::SELECTION"
        );
    }

    #[test]
    fn install_selection_updates_accessor() {
        let c = parse("#abcdef");
        install_selection(c);
        assert_eq!(selection(), c);
        // Restore the default so the process-wide cell doesn't leak into
        // other tests.
        install_selection(parse(hex::SELECTION));
    }

    // A1: the bus theme the kit broadcasts as its default must read back
    // as exactly the kit's default atoms, so the brief pre-replay frame
    // and the seeded steady state agree.
    #[test]
    fn default_bus_theme_reads_back_as_default_atoms() {
        assert_eq!(atoms_from_bus_theme(&to_bus_theme()), Atoms::default());
    }

    // A3: the hover elevation must come from the seed's real `bg-hover`
    // token, not a different surface step.
    #[test]
    fn hover_atom_reads_bg_hover_not_bg_tertiary() {
        let atoms = atoms_from_bus_theme(&BusTheme::default());
        assert_eq!(atoms.bg_hover, parse(hex::BG_HOVER));
        // Seed uses the same step for tertiary + hover; still must load
        // via the `bg-hover` token binding, not hard-coded elsewhere.
        assert_eq!(atoms.bg_hover, parse("#1e2533"));
    }

    // Sub-decision (A4): the seed speaks the kit's font-role vocabulary,
    // not the old font-sans/font-mono placeholders.
    #[test]
    fn seed_speaks_font_role_vocabulary() {
        let tokens = &BusTheme::default().palette.tokens;
        for role in ["font-ui", "font-ui-medium", "font-display", "font-chrome", "font-mono"] {
            assert!(tokens.contains_key(role), "seed missing {role}");
        }
        assert!(!tokens.contains_key("font-sans"), "seed still carries font-sans");
    }

    // The seed's font roles must resolve to the kit's default font table.
    #[test]
    fn seed_fonts_resolve_to_default_table() {
        assert_eq!(
            fonts_from_bus_theme(&BusTheme::default()),
            crate::fonts::Fonts::default()
        );
    }

    // The writelist (atoms→bus) must cover every token the readlist
    // (bus→atoms) consumes, so no editable atom can silently fail to
    // persist. Trivially true while both share ATOM_BINDINGS — this
    // guards against a future split.
    #[test]
    fn writelist_covers_readlist() {
        let written = bus_theme_from_atoms(&Atoms::default());
        for binding in ATOM_BINDINGS {
            assert!(
                written.palette.tokens.contains_key(binding.token),
                "atom token {} is read but never written",
                binding.token
            );
        }
    }

    // overlay(): window fill (background.base.color) must be transparent so
    // the OS window is see-through; non-base tiers stay opaque so kit
    // chrome (card, popover, button) renders correctly; base text is readable.
    #[test]
    fn overlay_chrome_theme() {
        let t = overlay(&default_theme());
        let ext = t.extended_palette();
        assert_eq!(ext.background.base.color.a, 0.0, "base must be transparent");
        assert!(ext.background.weak.color.a > 0.0, "weak must be opaque");
        assert!(ext.background.strong.color.a > 0.0, "strong must be opaque");
        assert!(ext.background.base.text.a > 0.0, "base text must be readable");
    }

    // overlay must preserve sola atom tiers — not iced Extended::generate greys.
    #[test]
    fn overlay_preserves_sola_background_tiers() {
        let base = default_theme();
        let base_ext = base.extended_palette();
        let themed = overlay(&base);
        let ext = themed.extended_palette();
        assert_eq!(
            ext.background.weaker.color, base_ext.background.weaker.color,
            "weaker must stay raised atom, not iced mid-grey"
        );
        assert_eq!(
            ext.background.stronger.color, base_ext.background.stronger.color,
            "stronger must stay border atom path"
        );
        assert_eq!(
            ext.background.strong.color, base_ext.background.strong.color,
            "strong must stay hover atom"
        );
        assert_eq!(
            ext.background.base.text, base_ext.background.base.text,
            "base text must stay sola fg"
        );
        assert_eq!(
            ext.primary.base.color, base_ext.primary.base.color,
            "primary accent must survive overlay"
        );
        assert_eq!(
            ext.secondary.base.text, base_ext.secondary.base.text,
            "secondary muted text must survive overlay"
        );
    }

    // menubar(): background must be opaque black; accent (primary) unchanged.
    #[test]
    fn menubar_chrome_theme() {
        let t = menubar(&default_theme(), Color::BLACK);
        let ext = t.extended_palette();
        let bg = ext.background.base.color;
        assert!(bg.a > 0.0, "menubar base must be opaque");
        assert!(bg.r < 0.1 && bg.g < 0.1 && bg.b < 0.1, "menubar base must be black-ish");
        assert_eq!(
            ext.primary.base.color,
            default_theme().extended_palette().primary.base.color,
            "accent must be unchanged"
        );
    }

    // menubar rebinds only base/weakest fill; keeps sola primary/secondary/mid-tiers.
    #[test]
    fn menubar_preserves_sola_tiers_with_custom_bg() {
        let base = default_theme();
        let base_ext = base.extended_palette();
        let menubar_bg = parse("#000000");
        let themed = menubar(&base, menubar_bg);
        let ext = themed.extended_palette();
        assert_eq!(
            ext.background.base.color, menubar_bg,
            "background.base.color must be the supplied menubar bg"
        );
        assert_eq!(
            ext.background.weakest.color, menubar_bg,
            "weakest must match menubar strip fill"
        );
        assert_eq!(
            ext.background.base.text, base_ext.background.base.text,
            "menubar text must stay sola fg"
        );
        assert_eq!(
            ext.primary.base.color, base_ext.primary.base.color,
            "primary.base must be unchanged"
        );
        assert_eq!(
            ext.secondary.base.text, base_ext.secondary.base.text,
            "secondary.base.text must stay muted"
        );
        assert_eq!(
            ext.background.weaker.color, base_ext.background.weaker.color,
            "raised mid-tier must not be recolored to black"
        );
        assert_eq!(
            ext.background.strong.color, base_ext.background.strong.color,
            "hover mid-tier must not be recolored to black"
        );
    }

    #[test]
    fn try_parse_eight_hex_roundtrip() {
        let c = try_parse("#2c2c2ecc").expect("8-hex parses");
        assert!((c.a - 0.8).abs() < 0.01, "alpha ≈ 0.8, got {}", c.a);
        assert_eq!(color_to_hex(c), "#2c2c2ecc");
    }

    #[test]
    fn color_to_hex_opaque_stays_six_digits() {
        let c = try_parse("#1c1c1e").expect("6-hex parses");
        assert_eq!(c.a, 1.0);
        assert_eq!(color_to_hex(c), "#1c1c1e");
    }

    #[test]
    fn seed_surfaces_are_graphite() {
        let atoms = Atoms::default();
        assert_eq!(atoms.bg, parse("#0c0e12"));
        assert_eq!(atoms.bg_raised, parse("#151922"));
        assert_eq!(atoms.accent, parse("#3dd6f5"), "graphite cyan accent");
        assert_eq!(atoms.selection, parse("#163842"), "quiet selection");
        // Not mac greys or Primer canvas
        assert_ne!(atoms.bg, parse("#1c1c1e"));
        assert_ne!(atoms.bg, parse("#0d1117"));
    }

    #[test]
    fn switcher_defaults_are_cmd_tab_hud() {
        let s = ShellStyle::default();
        assert_eq!(color_to_hex(s.switcher_bg), "#1c1c1ee6");
        assert_eq!(color_to_hex(s.switcher_border), "#ffffff1a");
        // Soft light plate under icon — not cyan, not selection-atom teal
        assert_eq!(color_to_hex(s.switcher_icon_bg), "#ffffff2e");
        assert_eq!(color_to_hex(s.switcher_icon_fg_sel), "#f5f5f7");
        assert_eq!(s.switcher_pad, 14.0);
        assert_eq!(s.switcher_tile_pad, 8.0);
    }

    #[test]
    fn shell_style_from_seed_matches_defaults() {
        // BusTheme::default() seeds the shell-* tokens (Task 1), and
        // ShellStyle::default() parses the same constant strings — the
        // two must agree byte-for-byte for preset resync matching.
        assert_eq!(shell_style_from_bus_theme(&BusTheme::default()), ShellStyle::default());
    }

    #[test]
    fn shell_style_defaults_from_empty_palette() {
        let empty = BusTheme { palette: Default::default(), components: Default::default() };
        assert_eq!(shell_style_from_bus_theme(&empty), ShellStyle::default());
    }

    #[test]
    fn shell_style_bus_roundtrip() {
        let mut style = ShellStyle::default();
        // parse() quantizes to u8 channels, so equality after the string
        // round-trip is exact. Don't use raw f32 alphas here (0.5 → 0x80
        // → 128/255 ≠ 0.5).
        style.switcher_bg = parse("#ffb80080");
        style.switcher_pad = 48.0;
        let bus = bus_theme_with_shell(BusTheme::default(), &style);
        assert_eq!(shell_style_from_bus_theme(&bus), style);
    }

    #[test]
    fn shell_style_malformed_token_falls_back() {
        let mut bus = BusTheme::default();
        bus.palette.tokens.get_mut("shell-switcher-pad").unwrap().value = "garbage".into();
        let style = shell_style_from_bus_theme(&bus);
        assert_eq!(style.switcher_pad, ShellStyle::default().switcher_pad);
    }
}
